// A processor block's budget in milliseconds, first for its first block; 0 for none.
export function processorBlockBudgetMs(hardBlocks, frames, sampleRate, first) {
    return hardBlocks === 0 ? 0.0 : Math.max(first ? 100.0 : 1.0, Math.ceil(hardBlocks * 1000.0 * frames / sampleRate));
}

